// Fuentes que se revisan en cada corrida.
//
// tipo "rss"  → feed RSS/Atom.
// tipo "html" → página con enlaces a notas; se toman los <a> cuyo href calza
//               con `patron`. Sirve de respaldo cuando el feed no existe o
//               el sitio lo cambia.
// oficial     → autoridad sanitaria: pasa primero y gana a un medio cuando la
//               misma noticia sale en los dos.
// filtrar     → la fuente publica mucho que no es regulatorio (Minsal): solo
//               pasan a la IA las notas cuyo título trae una palabra clave.
//
// Para agregar una fuente basta sumar una línea acá.
const FUENTES = [
  { nombre: 'ISP · noticias (feed)', tipo: 'rss',  url: 'https://www.ispch.gob.cl/noticia/feed/', fuente: 'ISP', ambito: 'Chile', oficial: true },
  { nombre: 'ISP · alertas (feed)',  tipo: 'rss',  url: 'https://www.ispch.gob.cl/alerta/feed/',  fuente: 'ISP', ambito: 'Chile', oficial: true },
  { nombre: 'ISP · portada',         tipo: 'html', url: 'https://www.ispch.gob.cl/', patron: '/(noticia|alerta)/[^/?#]+/?$', fuente: 'ISP', ambito: 'Chile', oficial: true },
  { nombre: 'Minsal',                tipo: 'rss',  url: 'https://www.minsal.cl/feed/', fuente: 'Minsal', ambito: 'Chile', oficial: true, filtrar: true },
  { nombre: 'FDA · comunicados',     tipo: 'rss',  url: 'https://www.fda.gov/about-fda/contact-fda/stay-informed/rss-feeds/press-releases/rss.xml', fuente: 'FDA', ambito: 'Internacional', oficial: true },
  { nombre: 'FDA · MedWatch',        tipo: 'rss',  url: 'https://www.fda.gov/about-fda/contact-fda/stay-informed/rss-feeds/medwatch/rss.xml', fuente: 'FDA', ambito: 'Internacional', oficial: true },
  { nombre: 'EMA · noticias',        tipo: 'rss',  url: 'https://www.ema.europa.eu/en/news.xml', fuente: 'EMA', ambito: 'Internacional', oficial: true },
];

return FUENTES.map((f) => ({ json: f }));

// ── Bloque común (igual en todos los nodos de código de este flujo) ─────────
const CONFIG = {
  VENTANA_DIAS: 3,        // notas publicadas hace más de esto no entran
  MAX_POR_CORRIDA: 12,    // tope de notas que lee la IA por corrida (cuota de Groq)
  MAX_NOTICIAS: 60,       // largo máximo de la lista publicada; git guarda el resto
  DIAS_RECUERDO: 45,      // cuánto recuerda n8n las notas ya juzgadas
  ZONA: 'America/Santiago',
};

function hoyChile(d = new Date()) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: CONFIG.ZONA }).format(d); // AAAA-MM-DD
}

function diasEntre(isoA, isoB) {
  return Math.round((Date.parse(`${isoB}T12:00:00Z`) - Date.parse(`${isoA}T12:00:00Z`)) / 86400000);
}

/**
 * Parser de URL propio: el sandbox del nodo Code de n8n no trae `URL`
 * (comprobado en n8n 1.123). Acepta relativas si se pasa `base`.
 */
function parsearUrl(s, base) {
  s = String(s ?? '').trim().replace(/ /g, '%20');
  if (base && !/^[a-z][a-z0-9+.-]*:/i.test(s)) {
    const b = parsearUrl(base);
    if (!b) return null;
    if (s.startsWith('//')) s = `${b.protocol}${s}`;
    else if (s.startsWith('/')) s = `${b.protocol}//${b.host}${s}`;
    else s = `${b.protocol}//${b.host}${b.pathname.replace(/[^/]*$/, '')}${s}`;
  }
  const m = s.match(/^(https?:)\/\/([^/?#\s:@]+)(?::(\d+))?([^?#\s]*)(\?[^#\s]*)?(#\S*)?$/i);
  if (!m) return null;
  const hostname = m[2].toLowerCase();
  return {
    protocol: m[1].toLowerCase(),
    hostname,
    host: hostname + (m[3] ? `:${m[3]}` : ''),
    pathname: m[4] || '/',
    search: m[5] && m[5] !== '?' ? m[5] : '',
  };
}

/** URL publicable: https, sin parámetros de seguimiento ni ancla. */
function normalizarUrl(u) {
  const x = parsearUrl(u);
  if (!x) return null;
  const params = x.search
    .slice(1)
    .split('&')
    .filter((kv) => kv && !/^(utm_|fbclid|gclid|mc_|ref=|source=)/i.test(kv));
  return `https://${x.host}${x.pathname}${params.length ? `?${params.join('&')}` : ''}`;
}

/** Clave para comparar URLs: sin www, sin barra final, sin protocolo. */
function claveUrl(u) {
  const x = parsearUrl(normalizarUrl(u));
  if (!x) return null;
  return (x.hostname.replace(/^www\./, '') + x.pathname.replace(/\/+$/, '') + x.search).toLowerCase();
}

function dominio(u) {
  return parsearUrl(u)?.hostname ?? '';
}

function decodificarEntidades(s) {
  const nombradas = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', laquo: '«', raquo: '»',
    ldquo: '“', rdquo: '”', lsquo: '‘', rsquo: '’', ndash: '–', mdash: '—', hellip: '…',
    aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó', uacute: 'ú', ntilde: 'ñ', uuml: 'ü',
    Aacute: 'Á', Eacute: 'É', Iacute: 'Í', Oacute: 'Ó', Uacute: 'Ú', Ntilde: 'Ñ', ordm: 'º', ordf: 'ª', deg: '°' };
  return String(s ?? '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&([a-z]+);/gi, (m, n) => nombradas[n] ?? m);
}

function textoPlano(html) {
  return decodificarEntidades(String(html ?? '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

/** Fecha ISO (AAAA-MM-DD, hora de Chile) desde cualquier formato que entienda Date. */
function aFechaIso(v) {
  if (!v) return null;
  const t = Date.parse(String(v).trim());
  return Number.isNaN(t) ? null : hoyChile(new Date(t));
}

// Palabras que delatan una nota regulatoria. Solo se usan con las fuentes
// marcadas `filtrar` y para ordenar: la decisión final es de la IA.
const PALABRAS_CLAVE = /medicament|f[aá]rmac|farmac|\bisp\b|anamed|registro sanitario|cosm[eé]tic|suplement|dispositiv|retiro|lote|alerta sanitaria|farmacovigil|cenabast|receta|bioequivalen|vacuna|decreto|reglamento|\bdrug|medicine|device|cosmetic|supplement|recall|approv|guidance|\bema\b|chmp|prac/i;
// ─────────────────────────────────────────────────────────────────────────────

// Convierte cada feed (o portada HTML) en candidatas y deja un parte de salud
// por fuente. Sale SIEMPRE un solo ítem, aunque no haya candidatas: el parte de
// salud tiene que llegar al aviso final igual, porque una fuente que dejó de
// responder es justamente lo que nadie ve.

const fuentes = $('Fuentes').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json);
const hoy = hoyChile();

const candidatos = [];
const salud = { ok: [], caidas: [] };

function etiqueta(bloque, nombre) {
  const m = bloque.match(new RegExp(`<${nombre}(?:\\s[^>]*)?>([\\s\\S]*?)</${nombre}>`, 'i'));
  return m ? decodificarEntidades(m[1]).trim() : '';
}

function itemsRss(xml) {
  const bloques = xml.match(/<item[\s>][\s\S]*?<\/item>/gi) || xml.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];
  return bloques.map((b) => {
    let enlace = etiqueta(b, 'link');
    if (!enlace) {
      const m = b.match(/<link[^>]*href="([^"]+)"/i); // Atom
      enlace = m ? m[1] : '';
    }
    return {
      titulo: textoPlano(etiqueta(b, 'title')),
      url: enlace,
      fecha: aFechaIso(etiqueta(b, 'pubDate') || etiqueta(b, 'dc:date') || etiqueta(b, 'published') || etiqueta(b, 'updated')),
      extracto: textoPlano(etiqueta(b, 'description') || etiqueta(b, 'summary')).slice(0, 400),
    };
  });
}

function itemsHtml(html, base, patron) {
  const re = new RegExp(patron, 'i');
  const vistos = new Map();
  for (const m of html.matchAll(/<a\b[^>]*href="([^"#]+)"[^>]*>([\s\S]*?)<\/a>/gi)) {
    const x = parsearUrl(decodificarEntidades(m[1]), base);
    if (!x || !re.test(x.pathname)) continue;
    const url = `${x.protocol}//${x.host}${x.pathname}${x.search}`;
    let titulo = textoPlano(m[2]);
    // Enlaces tipo «Leer más»: el título sale del slug de la URL.
    if (titulo.length < 15) {
      const slug = x.pathname.split('/').filter(Boolean).pop() || '';
      try { titulo = decodeURIComponent(slug); } catch { titulo = slug; }
      titulo = titulo.replace(/-/g, ' ');
      titulo = titulo.charAt(0).toUpperCase() + titulo.slice(1);
    }
    // El mismo enlace suele aparecer en la foto y en el titular: se queda el texto más largo.
    if (!vistos.has(url) || titulo.length > vistos.get(url).titulo.length) {
      vistos.set(url, { titulo, url, fecha: null, extracto: '' });
    }
  }
  return [...vistos.values()].filter((x) => x.titulo.length >= 15);
}

fuentes.forEach((f, i) => {
  const r = respuestas[i] || {};
  const cuerpo = typeof r.data === 'string' ? r.data : '';
  if (r.error || !cuerpo) {
    salud.caidas.push(`${f.nombre}: ${r.error?.message || r.error?.description || 'respuesta vacía'}`.slice(0, 160));
    return;
  }

  const items = f.tipo === 'html' ? itemsHtml(cuerpo, f.url, f.patron) : itemsRss(cuerpo);
  if (!items.length) {
    // Un feed que responde pero sin ítems también es una falla: cambió el formato o la URL.
    salud.caidas.push(`${f.nombre}: respondió, pero sin notas reconocibles`);
    return;
  }
  salud.ok.push(`${f.nombre} (${items.length})`);

  for (const it of items) {
    const url = normalizarUrl(it.url);
    if (!url || !it.titulo) continue;
    // Las de portada HTML no traen fecha: pasan y la fecha se saca de la nota.
    if (it.fecha && diasEntre(it.fecha, hoy) > CONFIG.VENTANA_DIAS) continue;
    if (f.filtrar && !PALABRAS_CLAVE.test(`${it.titulo} ${it.extracto}`)) continue;
    candidatos.push({
      titulo: it.titulo,
      url,
      fecha_feed: it.fecha,
      extracto: it.extracto,
      fuente: f.fuente,
      ambito: f.ambito,
      oficial: Boolean(f.oficial),
      origen_busqueda: f.nombre,
    });
  }
});

return [{ json: { candidatos, salud } }];

// Búsquedas en medios. Los feeds oficiales cubren ISP, Minsal, FDA y EMA; esto
// encuentra lo que publican la prensa y los medios del sector en Chile
// (retiros de lotes que el ISP no pone en su feed, resoluciones comentadas,
// etc.). Cada consulta gasta 1 crédito de Tavily: 6 al día ≈ 180 al mes, dentro
// del plan gratuito (1.000/mes).
//
// Para apagar esta parte sin tocar nada más: desactivar el nodo «Buscar en
// Tavily» (clic derecho → Deactivate). El flujo sigue solo con los feeds.
const CONSULTAS = [
  'ISP Chile medicamentos registro sanitario',
  'ANAMED ISP resolución normativa',
  'retiro de lotes medicamento Chile ISP alerta',
  'dispositivos médicos Chile regulación ISP',
  'cosméticos Chile ISP sin registro sanitario',
  'suplementos alimentarios Chile Minsal ISP',
];

return CONSULTAS.map((query) => ({ json: { query } }));

// ── Bloque común (igual en todos los nodos de código de este flujo) ─────────
const CONFIG = {
  VENTANA_DIAS: 3,        // notas publicadas hace más de esto no entran
  MAX_POR_CORRIDA: 12,    // tope de notas que lee la IA por corrida (cuota de Groq)
  MAX_NOTICIAS: 60,       // largo máximo de la lista publicada; git guarda el resto
  DIAS_RECUERDO: 45,      // cuánto recuerda n8n las notas ya juzgadas
