// Palabras que delatan una nota regulatoria. Solo se usan con las fuentes
// marcadas `filtrar` y para ordenar: la decisión final es de la IA.
const PALABRAS_CLAVE = /medicament|f[aá]rmac|farmac|\bisp\b|anamed|registro sanitario|cosm[eé]tic|suplement|dispositiv|retiro|lote|alerta sanitaria|farmacovigil|cenabast|receta|bioequivalen|vacuna|decreto|reglamento|\bdrug|medicine|device|cosmetic|supplement|recall|approv|guidance|\bema\b|chmp|prac/i;
// ─────────────────────────────────────────────────────────────────────────────

// Igual que «Parsear feeds»: sale un solo ítem con candidatas + parte de salud.
//
// Si el nodo «Buscar en Tavily» está desactivado, n8n le pasa acá las consultas
// tal cual (sin `results`): se informa como desactivado, no como caído.

const hoy = hoyChile();
const candidatos = [];
const salud = { ok: [], caidas: [] };
const entradas = $input.all().map((i) => i.json);

// Medios que no aportan: agregadores, redes y sitios de empleo.
const EXCLUIR = /(^|\.)(facebook|instagram|x|twitter|tiktok|youtube|linkedin|news\.google|msn|yahoo|laborum|trabajando|computrabajo)\./i;

const desactivado = entradas.length > 0 && entradas.every((e) => e.query && !('results' in e) && !e.error);
if (desactivado) {
  salud.ok.push('Tavily (desactivado)');
} else {
  let n = 0;
  entradas.forEach((e, i) => {
    if (e.error || !Array.isArray(e.results)) {
      salud.caidas.push(`Tavily, consulta ${i + 1}: ${e.error?.message || 'respuesta sin resultados'}`.slice(0, 160));
      return;
    }
    for (const r of e.results) {
      const url = normalizarUrl(r.url);
      if (!url || EXCLUIR.test(dominio(url))) continue;
      const fecha = aFechaIso(r.published_date);
      if (fecha && diasEntre(fecha, hoy) > CONFIG.VENTANA_DIAS) continue;
      n++;
      candidatos.push({
        titulo: textoPlano(r.title),
        url,
        fecha_feed: fecha,
        extracto: textoPlano(r.content).slice(0, 400),
        fuente: null, // se resuelve con el dominio en «Validar»
        ambito: null, // lo decide la IA
        oficial: /(^|\.)(ispch\.gob\.cl|minsal\.cl|cenabast\.cl|fda\.gov|ema\.europa\.eu)$/.test(dominio(url)),
        origen_busqueda: `Tavily: ${entradas[i].query ?? ''}`.slice(0, 80),
      });
    }
  });
  if (!salud.caidas.length) salud.ok.push(`Tavily (${n})`);
}

return [{ json: { candidatos, salud } }];

