// Lee el JSON que devolvió la API de contenidos de GitHub.
function leerArchivo(r) {
  if (!r || typeof r.content !== 'string' || !r.sha) {
    throw new Error('No se pudo leer data/noticias.json desde GitHub; no se sigue para no publicar un archivo vacío encima.');
  }
  const texto = typeof Buffer !== 'undefined'
    ? Buffer.from(r.content, 'base64').toString('utf-8')
    : decodeURIComponent(escape(atob(r.content.replace(/\s/g, ''))));
  const datos = JSON.parse(texto);
  if (!Array.isArray(datos.noticias)) throw new Error('data/noticias.json no trae la lista "noticias".');
  return datos;
}

