function meta(html, ...nombres) {
  for (const n of nombres) {
    const re1 = new RegExp(`<meta[^>]+(?:property|name|itemprop)=["']${n}["'][^>]*content=["']([^"']+)["']`, 'i');
    const re2 = new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]*(?:property|name|itemprop)=["']${n}["']`, 'i');
    const m = html.match(re1) || html.match(re2);
    if (m) return decodificarEntidades(m[1]).trim();
  }
  return null;
}

function fechaDePagina(html) {
  const m = meta(html, 'article:published_time', 'og:published_time', 'datePublished', 'pubdate', 'publish-date', 'date', 'DC.date.issued');
  if (m) return aFechaIso(m);
  const ld = html.match(/"datePublished"\s*:\s*"([^"]+)"/i);
  if (ld) return aFechaIso(ld[1]);
  const t = html.match(/<time[^>]+datetime=["']([^"']+)["']/i);
  return t ? aFechaIso(t[1]) : null;
}

function cuerpoDeNota(html) {
  let h = html
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|noscript|svg|iframe|form|header|footer|nav|aside)\b[\s\S]*?<\/\1>/gi, ' ');
  const article = h.match(/<article\b[\s\S]*?<\/article>/gi);
  const main = h.match(/<main\b[\s\S]*?<\/main>/i);
  const largo = (s) => textoPlano(s).length;
  if (article) {
    const mayor = article.sort((a, b) => largo(b) - largo(a))[0];
    if (largo(mayor) > 400) h = mayor;
  } else if (main && largo(main[0]) > 400) {
    h = main[0];
  }
  // Saltos en los bloques para que el texto no quede en una sola línea.
  return textoPlano(h.replace(/<\/(p|h[1-6]|li|tr|div|br)\s*>/gi, ' \n ').replace(/<br\s*\/?>/gi, ' \n '));
}

return candidatas.map((c, i) => {
  const r = paginas[i] || {};
  const html = typeof r.data === 'string' ? r.data : '';
  const texto = html ? cuerpoDeNota(html).slice(0, 7000) : '';
  const fechaPagina = html ? fechaDePagina(html) : null;
  const sitio = html ? meta(html, 'og:site_name') : null;
  const tituloPagina = html ? meta(html, 'og:title') : null;

  let saltar = null;
  if (r.error || !html) saltar = `no se pudo abrir la nota (${r.error?.message || 'respuesta vacía'})`.slice(0, 140);
  else if (texto.length < 300) saltar = 'la nota no trae texto suficiente';
  else if (fechaPagina && diasEntre(fechaPagina, hoy) > CONFIG.VENTANA_DIAS) saltar = `nota antigua (${fechaPagina})`;

  const usuario = [
    `FUENTE: ${c.fuente || sitio || dominio(c.url)}`,
    `URL: ${c.url}`,
    `FECHA SEGÚN EL FEED O LA PÁGINA: ${fechaPagina || c.fecha_feed || 'desconocida'}`,
    `HOY ES: ${hoy}`,
    '',
    `TITULAR ORIGINAL: ${tituloPagina || c.titulo}`,
    '',
    'TÍTULOS YA PUBLICADOS:',
    ...(c.recientes || []).map((t) => `- ${t}`),
    '',
    'MISMA TANDA:',
    ...(c.misma_tanda || []).map((t) => `- ${t}`),
    '',
    '=== TEXTO DE LA NOTA ===',
    texto,
    '=== FIN DEL TEXTO ===',
  ].join('\n');

  const cuerpo_llm = saltar
    ? { model: MODELO_VACIO, messages: [{ role: 'user', content: 'Responde solo: {}' }], max_completion_tokens: 5 }
    : {
        model: MODELO,
        temperature: 0.1,
        reasoning_effort: 'low',
        max_completion_tokens: 1500,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: SISTEMA },
          { role: 'user', content: usuario },
        ],
      };

  return {
    json: {
      ...c,
      recientes: undefined,
      misma_tanda: undefined,
      texto,
      fecha_pagina: fechaPagina,
      sitio,
      titulo_pagina: tituloPagina,
      saltar,
      cuerpo_llm,
    },
  };
});

