/** Parecido entre dos titulares (Jaccard sobre palabras de 4+ letras). */
function parecido(a, b) {
  const p = (s) => new Set(s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').match(/[a-z0-9]{4,}/g) || []);
  const A = p(a), B = p(b);
  if (!A.size || !B.size) return 0;
  let comun = 0;
  for (const x of A) if (B.has(x)) comun++;
  return comun / (A.size + B.size - comun);
}

const aceptadasEnTanda = [];

return notas.map((n, i) => {
  const salida = { url: n.url, clave: n.clave, titulo_original: n.titulo, origen_busqueda: n.origen_busqueda, juzgada: false, aceptada: false, motivo: null, noticia: null, importancia: 0 };
  const rechazar = (motivo) => ({ json: { ...salida, motivo } });

  if (n.saltar) {
    // Una nota que no se pudo abrir NO se marca como juzgada: se reintenta en
    // la próxima corrida (mientras siga dentro de la ventana de días).
    salida.juzgada = /antigua|texto suficiente/.test(n.saltar);
    return rechazar(n.saltar);
  }

  const r = respuestas[i] || {};
  if (r.error || !r.choices) return rechazar(`la IA no respondió (${r.error?.message || 'sin choices'})`.slice(0, 140));

  let ia;
  try {
    ia = JSON.parse(r.choices[0].message.content);
  } catch {
    return rechazar('la IA no devolvió JSON válido');
  }
  salida.juzgada = true;

  if (ia.relevante !== true) return rechazar(`no regulatoria: ${ia.motivo || 'sin motivo'}`.slice(0, 160));
  if (ia.duplicado_de) return rechazar(`repetida: «${String(ia.duplicado_de).slice(0, 80)}»`);

  const titulo = String(ia.titulo || '').replace(/\s+/g, ' ').trim();
  const resumen = String(ia.resumen || '').replace(/\s+/g, ' ').trim();
  if (titulo.length < 20 || titulo.length > 200) return rechazar(`título fuera de largo (${titulo.length})`);
  if (resumen.length < 40 || resumen.length > 400) return rechazar(`resumen fuera de largo (${resumen.length})`);
  if (!CATEGORIAS.includes(ia.categoria)) return rechazar(`categoría inválida: ${ia.categoria}`);

  // Fecha: manda la de la página o el feed (datos de máquina); la que leyó la
  // IA en el texto es el último recurso.
  const fecha = n.fecha_pagina || n.fecha_feed || (/^\d{4}-\d{2}-\d{2}$/.test(ia.fecha || '') ? ia.fecha : null);
  if (!fecha) return rechazar('sin fecha de publicación verificable');
  const edad = diasEntre(fecha, hoy);
  if (edad < -1) return rechazar(`fecha futura (${fecha})`);
  if (edad > CONFIG.VENTANA_DIAS + 1) return rechazar(`nota antigua (${fecha})`);

  // Cada cifra del título y del resumen tiene que estar en la nota. Es la
  // defensa principal contra un número inventado o mal copiado.
  const enNota = new Set(cifras(`${n.texto} ${n.titulo_pagina || ''} ${n.titulo}`));
  const inventadas = [...new Set(cifras(`${titulo} ${resumen}`))].filter((x) => !enNota.has(x));
  if (inventadas.length) return rechazar(`cifras que no están en la nota: ${inventadas.join(', ')}`);

  // Segunda red contra repetidas, sin depender de la IA.
  const repetida = [...recientes, ...aceptadasEnTanda].find((t) => parecido(t, titulo) >= 0.6);
  if (repetida) return rechazar(`repetida (parecido alto): «${repetida.slice(0, 80)}»`);

  const ambito = n.ambito || (ia.ambito === 'Chile' ? 'Chile' : 'Internacional');
  const importancia = Math.max(1, Math.min(5, parseInt(ia.importancia, 10) || 3));
  aceptadasEnTanda.push(titulo);

  return {
    json: {
      ...salida,
      aceptada: true,
      importancia,
      oficial: n.oficial,
      noticia: {
        titulo,
        resumen,
        categoria: ia.categoria,
        ambito,
        fecha,
        fuente: nombreFuente(n.url, n.fuente, n.sitio),
        url: n.url,
        origen: 'n8n',
        agregada: new Date().toISOString(),
      },
    },
  };
});

// ── Bloque común (igual en todos los nodos de código de este flujo) ─────────
const CONFIG = {
  VENTANA_DIAS: 3,        // notas publicadas hace más de esto no entran
  MAX_POR_CORRIDA: 12,    // tope de notas que lee la IA por corrida (cuota de Groq)
  MAX_NOTICIAS: 60,       // largo máximo de la lista publicada; git guarda el resto
  DIAS_RECUERDO: 45,      // cuánto recuerda n8n las notas ya juzgadas
  ZONA: 'America/Santiago',
};

function hoyChile(d = new Date()) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: CONFIG.ZONA }).format(d); // AAAA-MM-DD
}

function diasEntre(isoA, isoB) {
  return Math.round((Date.parse(`${isoB}T12:00:00Z`) - Date.parse(`${isoA}T12:00:00Z`)) / 86400000);
}

/**
 * Parser de URL propio: el sandbox del nodo Code de n8n no trae `URL`
 * (comprobado en n8n 1.123). Acepta relativas si se pasa `base`.
 */
function parsearUrl(s, base) {
  s = String(s ?? '').trim().replace(/ /g, '%20');
  if (base && !/^[a-z][a-z0-9+.-]*:/i.test(s)) {
    const b = parsearUrl(base);
    if (!b) return null;
    if (s.startsWith('//')) s = `${b.protocol}${s}`;
    else if (s.startsWith('/')) s = `${b.protocol}//${b.host}${s}`;
    else s = `${b.protocol}//${b.host}${b.pathname.replace(/[^/]*$/, '')}${s}`;
  }
  const m = s.match(/^(https?:)\/\/([^/?#\s:@]+)(?::(\d+))?([^?#\s]*)(\?[^#\s]*)?(#\S*)?$/i);
  if (!m) return null;
  const hostname = m[2].toLowerCase();
  return {
    protocol: m[1].toLowerCase(),
    hostname,
    host: hostname + (m[3] ? `:${m[3]}` : ''),
    pathname: m[4] || '/',
    search: m[5] && m[5] !== '?' ? m[5] : '',
  };
}

/** URL publicable: https, sin parámetros de seguimiento ni ancla. */
function normalizarUrl(u) {
  const x = parsearUrl(u);
  if (!x) return null;
  const params = x.search
    .slice(1)
    .split('&')
    .filter((kv) => kv && !/^(utm_|fbclid|gclid|mc_|ref=|source=)/i.test(kv));
  return `https://${x.host}${x.pathname}${params.length ? `?${params.join('&')}` : ''}`;
}

/** Clave para comparar URLs: sin www, sin barra final, sin protocolo. */
function claveUrl(u) {
  const x = parsearUrl(normalizarUrl(u));
  if (!x) return null;
  return (x.hostname.replace(/^www\./, '') + x.pathname.replace(/\/+$/, '') + x.search).toLowerCase();
}

function dominio(u) {
  return parsearUrl(u)?.hostname ?? '';
}

function decodificarEntidades(s) {
  const nombradas = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', laquo: '«', raquo: '»',
    ldquo: '“', rdquo: '”', lsquo: '‘', rsquo: '’', ndash: '–', mdash: '—', hellip: '…',
    aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó', uacute: 'ú', ntilde: 'ñ', uuml: 'ü',
    Aacute: 'Á', Eacute: 'É', Iacute: 'Í', Oacute: 'Ó', Uacute: 'Ú', Ntilde: 'Ñ', ordm: 'º', ordf: 'ª', deg: '°' };
  return String(s ?? '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&([a-z]+);/gi, (m, n) => nombradas[n] ?? m);
}

function textoPlano(html) {
  return decodificarEntidades(String(html ?? '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

/** Fecha ISO (AAAA-MM-DD, hora de Chile) desde cualquier formato que entienda Date. */
function aFechaIso(v) {
  if (!v) return null;
  const t = Date.parse(String(v).trim());
  return Number.isNaN(t) ? null : hoyChile(new Date(t));
}

// Palabras que delatan una nota regulatoria. Solo se usan con las fuentes
// marcadas `filtrar` y para ordenar: la decisión final es de la IA.
const PALABRAS_CLAVE = /medicament|f[aá]rmac|farmac|\bisp\b|anamed|registro sanitario|cosm[eé]tic|suplement|dispositiv|retiro|lote|alerta sanitaria|farmacovigil|cenabast|receta|bioequivalen|vacuna|decreto|reglamento|\bdrug|medicine|device|cosmetic|supplement|recall|approv|guidance|\bema\b|chmp|prac/i;
// ─────────────────────────────────────────────────────────────────────────────

// Arma el data/noticias.json nuevo, lo valida entero con las reglas del sitio
// y prepara el commit y el aviso.
//
// Se publica SIEMPRE, aunque no haya noticias nuevas: la fecha "actualizadas"
// y la bitácora "revision" son el latido que mira el vigía de frescura de
// GitHub. Si el archivo nuevo no pasa la validación, el nodo falla a propósito
// (salta el flujo de alertas) y no se publica nada.

const leido = $('Leer noticias.json').first().json;
const archivo = leerArchivo(leido);

const hoy = hoyChile();
const ahora = new Date().toISOString();

// 1. Lo que llegó de «Validar» (o el ítem { vacio } si no había candidatas).
const resultados = $input.all().map((i) => i.json).filter((r) => !r.vacio);
const aceptadas = resultados.filter((r) => r.aceptada).sort((a, b) => b.importancia - a.importancia);
const descartadas = resultados.filter((r) => !r.aceptada);

// 2. Destacadas: a lo más una nueva por día, y solo de importancia 5. El
//    cuadro muestra las tres destacadas más recientes, así que una nueva empuja
//    a la más antigua fuera del cuadro (sigue en la lista de titulares).
const nuevas = aceptadas.map((r, idx) => ({ ...r.noticia, ...(idx === 0 && r.importancia >= 5 ? { destacada: true } : {}) }));

// 3. Lista final: nuevas + existentes (n8n nunca edita ni borra a mano lo que
//    ya estaba), sin URLs repetidas, de la más nueva a la más antigua, con tope.
const vistas = new Set();
const noticias = [...nuevas, ...archivo.noticias]
  .filter((n) => {
    const k = claveUrl(n.url);
    if (vistas.has(k)) return false;
    vistas.add(k);
    return true;
  })
  .sort((a, b) => b.fecha.localeCompare(a.fecha))
  .slice(0, CONFIG.MAX_NOTICIAS);

// 4. Parte de salud de las fuentes.
const salud = $('Unir fuentes').all().reduce(
  (acc, i) => ({ ok: [...acc.ok, ...(i.json.salud?.ok || [])], caidas: [...acc.caidas, ...(i.json.salud?.caidas || [])] }),
  { ok: [], caidas: [] },
);

const nuevoArchivo = {
  actualizadas: hoy,
  revision: {
    ts: ahora,
    agregadas: nuevas.length,
    descartadas: descartadas.length,
    fuentes_ok: salud.ok,
    fuentes_caidas: salud.caidas,
  },
  noticias,
};

// 5. Validación completa. Copia de lib/noticias-validar.ts: si cambia allá,
//    cambiarla acá.
const problemas = problemasArchivo(nuevoArchivo);
if (problemas.length) {
  throw new Error(`El archivo nuevo no pasa la validación y NO se publicó:\n${problemas.slice(0, 10).join('\n')}`);
}

// 6. Notas ya juzgadas por la IA: «Recordar juzgadas» las anota DESPUÉS de
//    que el commit sale bien. Si el commit falla, mañana se vuelven a evaluar
//    en vez de perderse. Las que no se pudieron abrir no van: se reintentan.
const juzgadas = resultados.filter((r) => r.juzgada && r.clave).map((r) => r.clave);

// 7. Commit y aviso.
const texto = `${JSON.stringify(nuevoArchivo, null, 2)}\n`;
const contenido = typeof Buffer !== 'undefined'
  ? Buffer.from(texto, 'utf-8').toString('base64')
  : btoa(unescape(encodeURIComponent(texto)));

const commit = {
  message: nuevas.length
    ? `chore(noticias): ${nuevas.length} nueva(s) ${hoy}\n\n${nuevas.map((n) => `- ${n.fuente}: ${n.titulo}`).join('\n')}`
    : `chore(noticias): revisión ${hoy} sin noticias nuevas`,
  content: contenido,
  sha: leido.sha,
  branch: 'main',
};

const lineas = [
  `📰 RegulaMED · noticias ${hoy}`,
  nuevas.length ? `\n✅ Publicadas (${nuevas.length}):` : '\nSin noticias nuevas hoy.',
  ...nuevas.map((n) => `• ${n.destacada ? '★ ' : ''}[${n.fuente}] ${n.titulo}\n  ${n.url}`),
];
if (descartadas.length) {
  lineas.push(`\n🗂 Descartadas (${descartadas.length}):`);
  lineas.push(...descartadas.slice(0, 15).map((d) => `• ${d.titulo_original.slice(0, 90)} — ${d.motivo}`));
}
if (salud.caidas.length) {
  lineas.push('\n⚠️ Fuentes con problemas:');
  lineas.push(...salud.caidas.map((c) => `• ${c}`));
}
lineas.push(`\nFuentes OK: ${salud.ok.join(', ') || 'ninguna'}`);
if (!salud.ok.length) lineas.push('🚨 NINGUNA fuente respondió: revisar la red del VPS.');

return [{ json: { commit, juzgadas, aviso: lineas.join('\n').slice(0, 4000), agregadas: nuevas.length, descartadas: descartadas.length } }];

// ── Reglas del sitio (copia de lib/noticias-validar.ts) ─────────────────────
function esFechaIso(v) {
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
  const d = new Date(`${v}T12:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === v;
}

function problemasNoticia(o) {
  if (!o || typeof o !== 'object') return ['no es un objeto'];
  const p = [];
  if (typeof o.titulo !== 'string' || o.titulo.trim().length < 10 || o.titulo.length > 240) p.push('titulo: texto de 10 a 240 caracteres');
  if (o.resumen !== undefined && (typeof o.resumen !== 'string' || o.resumen.length > 500)) p.push('resumen: texto de hasta 500 caracteres');
  if (o.destacada === true && (typeof o.resumen !== 'string' || !o.resumen.trim())) p.push('resumen: obligatorio en las destacadas');
  if (!['farmaceuticos', 'cosmeticos', 'suplementos', 'dispositivos'].includes(o.categoria)) p.push('categoria inválida');
  if (o.ambito !== 'Chile' && o.ambito !== 'Internacional') p.push('ambito: Chile o Internacional');
  if (!esFechaIso(o.fecha)) p.push('fecha: AAAA-MM-DD');
  if (typeof o.fuente !== 'string' || !o.fuente.trim() || o.fuente.length > 40) p.push('fuente: texto de 1 a 40 caracteres');
  if (typeof o.url !== 'string' || parsearUrl(o.url)?.protocol !== 'https:') p.push('url: https://…');
  if (o.destacada !== undefined && typeof o.destacada !== 'boolean') p.push('destacada: true o false');
  if (o.origen !== undefined && o.origen !== 'manual' && o.origen !== 'n8n') p.push('origen: manual o n8n');
  return p;
}

function problemasArchivo(d) {
  const p = [];
  if (!esFechaIso(d.actualizadas)) p.push('actualizadas: AAAA-MM-DD');
  if (!Array.isArray(d.noticias)) return [...p, 'noticias: falta la lista'];
  const urls = new Set();
  d.noticias.forEach((n, i) => {
    for (const x of problemasNoticia(n)) p.push(`noticias[${i}] ${x}`);
    if (urls.has(n.url)) p.push(`noticias[${i}] url repetida`);
    urls.add(n.url);
  });
  if (!d.noticias.length) p.push('noticias: la lista quedó vacía');
  return p;
}

function leerArchivo(r) {
  if (!r || typeof r.content !== 'string' || !r.sha) throw new Error('No se pudo leer data/noticias.json desde GitHub.');
  const t = typeof Buffer !== 'undefined'
    ? Buffer.from(r.content, 'base64').toString('utf-8')
    : decodeURIComponent(escape(atob(r.content.replace(/\s/g, ''))));
  return JSON.parse(t);
}

