// ─────────────────────────────────────────────────────────────────────────────

// Solo corre si «Publicar en GitHub» respondió bien: recién ahí las notas
// juzgadas se dan por vistas y no se vuelven a mandar a la IA.
const memoria = $getWorkflowStaticData('global');
memoria.vistas = memoria.vistas || {};
const hoy = hoyChile();

for (const k of $('Armar archivo').first().json.juzgadas || []) memoria.vistas[k] = hoy;
for (const [k, f] of Object.entries(memoria.vistas)) {
  if (diasEntre(f, hoy) > CONFIG.DIAS_RECUERDO) delete memoria.vistas[k];
}

const commit = $input.first().json.commit || {};
return [{ json: { recordadas: Object.keys(memoria.vistas).length, commit_sha: commit.sha, commit_url: commit.html_url } }];
